/// <summary>
/// Client only. A free camera that flies through walls. In 'body' mode the player's body goes too,
/// so others see it fly, and it lands where the flight ends. In 'camera' mode only the view moves.
/// During a flight the game's controls are held, and with input on, W A S D, Space (up), C (down),
/// Shift (boost), Alt (crawl) and the mouse steer it. The player does not see their own body,
/// though others still do. Yaw is in degrees from +Y, rising to the left, and pitch is in degrees,
/// positive up. The server decides who can fly with Player.noclipAllowed, and for others, enable()
/// returns 'notAllowed'. Events are noclipChanged(active, reason), with the reason 'script',
/// 'sessionOver', 'viewLost' or 'notAllowed', and noclipAllowedChanged(allowed). (Client only.)
/// </summary>
public static class NoClip
{

    /// <summary>
    /// Starts a flight. Returns 'enabled', 'alreadyActive', or 'notAllowed' if the server does not
    /// allow this player to fly. The game reports the camera a frame later. Until then, getState,
    /// getPosition and similar reads give null, while setPose, setPosition, setRotation, lookAt and
    /// focus are kept and applied in order. (Client only.)
    /// </summary>
    /// <param name="options">Optional: `mode`, 'body' (default) or 'camera'; `input`, default true, so keys and mouse steer it; `showBody`, default false, where true lets the player see their body, for a camera showing the character from the front; `orbit`, { target: Vector3, distance: 0.5 to 50 m, default 3 }, where the camera circles the target, the mouse turns it and W and S change the distance; `keepAboveGround`, default true, which keeps it in front of the ground or a wall between it and the target; `look`, 'always' (default) or 'rightButton', which turns and moves only while the right button is held, so a focused page keeps the pointer and keys otherwise, as in an editor; `speed`, 0.05 to 400 m/s, default 12; `fov`, 20 to 140 degrees, by default the game's; `position` and `forward`, Vector3s for the start and look direction, by default the player's eyes.</param>
    /// <returns>string</returns>
    public static string Enable(object? options = null) => Sdk.Call<string>("ui", "NoClip", "enable", Sdk.Optional(options));

    /// <summary>
    /// Ends the flight. (Client only.)
    /// </summary>
    /// <param name="options">Optional: `keepPosition`, default true. In body mode, the body stays where the camera stopped, and with false it returns to where it took off.</param>
    /// <returns>void</returns>
    public static void Disable(object? options = null) => Sdk.Call("ui", "NoClip", "disable", Sdk.Optional(options));

    /// <summary>
    /// Whether a flight is running. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsActive() => Sdk.Call<bool>("ui", "NoClip", "isActive");

    /// <summary>
    /// Whether the server allows the local player to fly, which is true unless forbidden. While false,
    /// enable() returns 'notAllowed'. noclipAllowedChanged(allowed) fires when it changes. (Client
    /// only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsAllowed() => Sdk.Call<bool>("ui", "NoClip", "isAllowed");

    /// <summary>
    /// The flight, as { mode, input, position, forward, right, up, yaw, pitch, speed, fov, renderedFov,
    /// aspectRatio }, or null if not flying. (Client only.)
    /// </summary>
    /// <returns>object | null</returns>
    public static JsValue GetState() => Sdk.Call<JsValue>("ui", "NoClip", "getState");

    /// <summary>
    /// The camera's position, or null if not flying. (Client only.)
    /// </summary>
    /// <returns>Vector3 | null</returns>
    public static Kcds.Math.Vector3? GetPosition() => Sdk.Call<Kcds.Math.Vector3?>("ui", "NoClip", "getPosition");

    /// <summary>
    /// Moves the camera. Right after enable(), it is kept until the game reports the camera, then
    /// applied, returning true. Returns false if not flying. (Client only.)
    /// </summary>
    /// <param name="position">The new position.</param>
    /// <returns>boolean</returns>
    public static bool SetPosition(object? position) => Sdk.Call<bool>("ui", "NoClip", "setPosition", position);

    /// <summary>
    /// { yaw, pitch } in degrees, or null if not flying. (Client only.)
    /// </summary>
    /// <returns>{ yaw, pitch } | null</returns>
    public static JsValue GetRotation() => Sdk.Call<JsValue>("ui", "NoClip", "getRotation");

    /// <summary>
    /// Turns the camera, with parts left out keeping their value. (Client only.)
    /// </summary>
    /// <param name="rotation">{ yaw?, pitch? } in degrees.</param>
    /// <returns>boolean</returns>
    public static bool SetRotation(object? rotation) => Sdk.Call<bool>("ui", "NoClip", "setRotation", rotation);

    /// <summary>
    /// The direction the camera looks, or null if not flying. (Client only.)
