/// <summary>
/// Client only. Opens the game's character stage, with a figure dressed in the chosen look and a
/// panel of choices. It does not change the player's body or send anything.
/// characterCreatorChanged(appearance) follows every look the figure shows, and
/// characterCreatorClosed(appearance, reason) gives your script the accepted look, { gender, body,
/// head, hair, beard }, and null unless accepted. The reason is 'accepted', 'cancelled', 'closed',
/// 'replaced', 'unavailable' or 'interrupted'. To apply it, send it to the server and call
/// Player.setAppearance. For an editor of your own (a page or a NativeUI screen), open it with
/// `panel: false` and drive the figure with preview, frame, accept and cancel; `choices` limits
/// what can be chosen. (Client only.)
/// </summary>
public static class CharacterCreator
{

    /// <summary>
    /// Opens the creator, replacing one already open. Throws a TypeError for an unknown option or a
    /// part name list that is empty or too long, and a RangeError for a name that is no option of that
    /// part. (Client only.)
    /// </summary>
    /// <param name="options">Optional: `genders` ('male', 'female' or 'both', the default), `title`, `appearance` to start from (by default the player's own), `panel` (false: no panel of choices, your own editor drives the figure) and `choices` ({ body, head, hair, beard }: each a list of the option names that part may be, '' for the game's own; a part left out offers everything). The panel and random looks keep to the choices.</param>
    /// <returns>boolean</returns>
    public static bool Open(object? options = null) => Sdk.Call<bool>("ui", "CharacterCreator", "open", Sdk.Optional(options));

    /// <summary>
    /// Closes the creator with the reason 'closed'. Returns false if it is not open. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool Close() => Sdk.Call<bool>("ui", "CharacterCreator", "close");

    /// <summary>
    /// Whether the creator is open. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsOpen() => Sdk.Call<bool>("ui", "CharacterCreator", "isOpen");

    /// <summary>
    /// The look the figure shows now, { gender, body, head, hair, beard }, or null when the creator is
    /// not open. (Client only.)
    /// </summary>
    /// <returns>object | null</returns>
    public static JsValue Look() => Sdk.Call<JsValue>("ui", "CharacterCreator", "look");

    /// <summary>
    /// Dresses the figure in a look, as a choice in the panel does: for an editor of your own. Parts
    /// left out are the game's own. Returns false when the creator is not open. Throws a TypeError for
    /// a malformed look and a RangeError for a part the catalogue does not have, a beard the face
    /// cannot wear or a gender the creator does not offer. (Client only.)
    /// </summary>
    /// <param name="appearance">The look: { gender, body?, head?, hair?, beard? } with names from Appearances.</param>
    /// <returns>boolean</returns>
    public static bool Preview(object? appearance) => Sdk.Call<bool>("ui", "CharacterCreator", "preview", appearance);

    /// <summary>
    /// Points the stage's camera at the whole figure ('body') or close at its face ('face'). Returns
    /// false when the creator is not open. Throws a TypeError for another frame. (Client only.)
    /// </summary>
    /// <param name="frame">'body' or 'face'.</param>
    /// <returns>boolean</returns>
    public static bool Frame(object? frame) => Sdk.Call<bool>("ui", "CharacterCreator", "frame", frame);

    /// <summary>
    /// Closes the creator with the look the figure shows: characterCreatorClosed hears it with
    /// 'accepted'. Returns false when the creator is not open. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool Accept() => Sdk.Call<bool>("ui", "CharacterCreator", "accept");

    /// <summary>
    /// Closes the creator without a look: characterCreatorClosed hears null and 'cancelled'. Returns
    /// false when the creator is not open. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool Cancel() => Sdk.Call<bool>("ui", "CharacterCreator", "cancel");
}

/// <summary>
/// What client resources add to the player's Discord activity. KCDS already shows each stage from
/// startup through the menu to a server, with its logo, a timer and a link to its website. While
/// the player is on a server, a resource can set the server's name, shown as "KCDS - &lt;name&gt;",
/// the status line, the logo and small image with tooltips, and one button. KCDS's website button
/// is always second, and the activity's type, timestamps, party and secrets stay with KCDS. Setters
/// only prepare a field, and update() and setPresence() publish. Resources on one machine share one
/// activity. (Client only.)
/// </summary>
public static class Discord
{

    /// <summary>
    /// Prepares the server's name, up to 128 UTF-8 bytes. On the server, the line under KCDS reads
    /// "KCDS - &lt;name&gt;" rather than "Playing on &lt;server&gt;". The title stays KCDS. '' restores
    /// KCDS's line. (Client only.)
    /// </summary>
    /// <param name="value">The server's name.</param>
    /// <returns>void</returns>
    public static void SetName(object? value) => Sdk.Call("ui", "Discord", "setName", value);

    /// <summary>
    /// Prepares the status line, up to 128 UTF-8 bytes. update() publishes it while the player is on a
    /// server. (Client only.)
    /// </summary>
    /// <param name="value">The status line.</param>
    /// <returns>void</returns>
    public static void SetState(object? value) => Sdk.Call("ui", "Discord", "setState", value);

    /// <summary>
    /// Prepares the logo, an https image link of up to 128 UTF-8 bytes, shown on the server in place of
    /// the KCDS logo. '' restores the KCDS logo. (Client only.)
    /// </summary>
    /// <param name="value">An https image link.</param>
    /// <returns>void</returns>
    public static void SetLargeImage(object? value) => Sdk.Call("ui", "Discord", "setLargeImage", value);

    /// <summary>
    /// Prepares the logo's tooltip, up to 128 UTF-8 bytes, shown on the server in place of the KCDS
    /// version. (Client only.)
    /// </summary>
    /// <param name="value">The tooltip.</param>
    /// <returns>void</returns>
    public static void SetLargeText(object? value) => Sdk.Call("ui", "Discord", "setLargeText", value);

    /// <summary>
    /// Prepares the small image, up to 128 UTF-8 bytes. update() publishes it while the player is on a
    /// server. (Client only.)
    /// </summary>
    /// <param name="value">The image key.</param>
    /// <returns>void</returns>
    public static void SetSmallImage(object? value) => Sdk.Call("ui", "Discord", "setSmallImage", value);

    /// <summary>
    /// Prepares the small image's tooltip, up to 128 UTF-8 bytes. update() publishes it while the
    /// player is on a server. (Client only.)
    /// </summary>
    /// <param name="value">The tooltip.</param>
    /// <returns>void</returns>
    public static void SetSmallText(object? value) => Sdk.Call("ui", "Discord", "setSmallText", value);

    /// <summary>
    /// Prepares the images and tooltips together. (Client only.)
    /// </summary>
    /// <param name="assets">{ largeImage?, largeText?, smallImage?, smallText? }.</param>
    public static JsValue SetAssets(object? assets) => Sdk.Call<JsValue>("ui", "Discord", "setAssets", assets);

    /// <summary>
    /// Prepares the server's button, with a label of 1 to 32 UTF-8 bytes and an https link. It comes
    /// first on the server, and KCDS's "KCDS website" button is always second and cannot be removed.
    /// ('', '') removes the server's button. Discord shows buttons to people viewing the player's
    /// profile. (Client only.)
    /// </summary>
    /// <param name="label">The button's text.</param>
    /// <param name="url">An https link.</param>
    /// <returns>void</returns>
    public static void SetButton(object? label, object? url) => Sdk.Call("ui", "Discord", "setButton", label, url);

    /// <summary>
    /// Prepares several fields and publishes them, as update() does. (Client only.)
    /// </summary>
    /// <param name="options">{ name?, state?, largeImage?, largeText?, smallImage?, smallText?, button? }, where button is { label, url } or null. Any other field throws.</param>
    /// <returns>boolean: false while the player's Discord app is not connected.</returns>
    public static bool SetPresence(object? options = null) => Sdk.Call<bool>("ui", "Discord", "setPresence", Sdk.Optional(options));

    /// <summary>
    /// Publishes the prepared fields while the player is on a server. (Client only.)
    /// </summary>
    /// <returns>boolean: false while the player's Discord app is not connected.</returns>
    public static bool Update() => Sdk.Call<bool>("ui", "Discord", "update");

    /// <summary>
    /// Removes resources' fields from the activity, leaving KCDS's presence. (Client only.)
    /// </summary>
    /// <returns>boolean: false while the player's Discord app is not connected. Prepared fields are forgotten either way.</returns>
    public static bool Clear() => Sdk.Call<bool>("ui", "Discord", "clear");

    /// <summary>
    /// Forgets all prepared fields without publishing. (Client only.)
    /// </summary>
    /// <returns>void</returns>
    public static void Reset() => Sdk.Call("ui", "Discord", "reset");

    /// <summary>
    /// The Discord user signed in to the player's app, or '' until Discord has answered. (Client only.)
    /// </summary>
    /// <returns>string</returns>
    public static string GetUserId() => Sdk.Call<string>("ui", "Discord", "getUserId");

    /// <summary>
    /// Whether the player's Discord app is running and connected. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsAvailable() => Sdk.Call<bool>("ui", "Discord", "isAvailable");
}

/// <summary>
/// What this player's game draws of the plates above players, and short labels resources add above
/// them. None of this is sent to others. What the server sets on a plate with Player.setNameplate*
/// comes with the player. A label belongs to the resource that set it, and goes when that resource
/// stops. (Client only.)
/// </summary>
public static class Nameplates
{

    /// <summary>
    /// Shows or hides all plates on this screen. (Client only.)
    /// </summary>
    /// <param name="visible">A boolean.</param>
    /// <returns>void</returns>
    public static void SetVisible(object? visible) => Sdk.Call("ui", "Nameplates", "setVisible", visible);

    /// <summary>
    /// Whether plates show on this screen. True by default. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsVisible() => Sdk.Call<bool>("ui", "Nameplates", "isVisible");

    /// <summary>
    /// Shows or hides health bars on this screen. (Client only.)
    /// </summary>
    /// <param name="visible">A boolean.</param>
    /// <returns>void</returns>
    public static void SetHealthVisible(object? visible) => Sdk.Call("ui", "Nameplates", "setHealthVisible", visible);

    /// <summary>
    /// Whether health bars show on this screen. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsHealthVisible() => Sdk.Call<bool>("ui", "Nameplates", "isHealthVisible");

    /// <summary>
    /// Shows or hides names on this screen. (Client only.)
    /// </summary>
    /// <param name="visible"></param>
    /// <returns>void</returns>
    public static void SetNameVisible(object? visible) => Sdk.Call("ui", "Nameplates", "setNameVisible", visible);

    /// <summary>
    /// Whether names show on this screen. With health bars alone, each bar takes its name's place.
    /// (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsNameVisible() => Sdk.Call<bool>("ui", "Nameplates", "isNameVisible");

    /// <summary>
    /// Sets what a plate shows on this screen: 'both', 'name', 'health' or 'none'. (Client only.)
    /// </summary>
    /// <param name="mode"></param>
    /// <returns>void</returns>
    public static void SetMode(object? mode) => Sdk.Call("ui", "Nameplates", "setMode", mode);

    /// <summary>
    /// What a plate shows on this screen: 'both', 'name', 'health' or 'none'. (Client only.)
    /// </summary>
    /// <returns>string</returns>
    public static string GetMode() => Sdk.Call<string>("ui", "Nameplates", "getMode");

    /// <summary>
    /// Shows or hides the local player's own plate. (Client only.)
    /// </summary>
    /// <param name="visible">A boolean.</param>
    /// <returns>void</returns>
    public static void SetSelfVisible(object? visible) => Sdk.Call("ui", "Nameplates", "setSelfVisible", visible);

    /// <summary>
    /// Whether the local player's own plate shows. False by default. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsSelfVisible() => Sdk.Call<bool>("ui", "Nameplates", "isSelfVisible");

    /// <summary>
    /// Adds a short line above an entity's plate on this screen. '' removes it. (Client only.)
    /// </summary>
    /// <param name="entityId">The entity's network id.</param>
    /// <param name="text">The line, up to 256 UTF-8 bytes.</param>
    /// <param name="durationMs">How long it shows, 6000 by default and up to an hour. 0 or less keeps it until cleared.</param>
    /// <param name="color">A packed 0xAARRGGBB, or 0, the default, for the plate's colour.</param>
    public static JsValue SetLabel(object? entityId, object? text, object? durationMs = null, object? color = null) => Sdk.Call<JsValue>("ui", "Nameplates", "setLabel", entityId, text, Sdk.Optional(durationMs), Sdk.Optional(color));

    /// <summary>
    /// Removes the label from one entity. (Client only.)
    /// </summary>
    /// <param name="entityId">The entity.</param>
    public static JsValue ClearLabel(object? entityId) => Sdk.Call<JsValue>("ui", "Nameplates", "clearLabel", entityId);

    /// <summary>
    /// Removes all labels. (Client only.)
    /// </summary>
    public static JsValue ClearLabels() => Sdk.Call<JsValue>("ui", "Nameplates", "clearLabels");
}

/// <summary>
/// The emote catalogue, and which gesture each slot of this player's wheel plays. All gestures are
/// the game's animations. The layout is kept on this machine for the session, and resources there
/// share one wheel. (Client only.)
/// </summary>
public static class EmoteWheel
{

    /// <summary>
    /// The number of slots, which is 6. (Client only.)
    /// </summary>
    /// <returns>number</returns>
    public static double SlotTotal() => Sdk.Call<double>("ui", "EmoteWheel", "slotTotal");

    /// <summary>
    /// The catalogue id in each slot, clockwise from straight up. (Client only.)
    /// </summary>
    /// <returns>number[]</returns>
    public static double[] GetSlots() => Sdk.Call<double[]>("ui", "EmoteWheel", "getSlots");

    /// <summary>
    /// Puts an emote in one slot. With a bad slot or id it returns false and changes nothing. (Client
    /// only.)
    /// </summary>
    /// <param name="slot">The slot: 0 is straight up, continuing clockwise.</param>
    /// <param name="emoteId">A catalogue id.</param>
    /// <returns>boolean</returns>
    public static bool AssignSlot(object? slot, object? emoteId) => Sdk.Call<bool>("ui", "EmoteWheel", "assignSlot", slot, emoteId);

    /// <summary>
    /// Sets all slots together. With a wrong length or bad id it returns false and changes nothing.
    /// (Client only.)
    /// </summary>
    /// <param name="emoteIds">One catalogue id per slot.</param>
    /// <returns>boolean</returns>
    public static bool AssignSlots(object? emoteIds) => Sdk.Call<bool>("ui", "EmoteWheel", "assignSlots", emoteIds);

    /// <summary>
    /// Restores the default six: wave, big wave, nod, respectful nod, bow and cheer. (Client only.)
    /// </summary>
    public static JsValue Reset() => Sdk.Call<JsValue>("ui", "EmoteWheel", "reset");

    /// <summary>
    /// The emotes in catalogue order, each with its animation: fragment and tags, plus femaleTags where
    /// a woman's body differs. To play one on an NPC, call npc.playAnimation(fragment, { tags }) on the
    /// server. (Client only.)
    /// </summary>
    /// <returns>{ id: number; name: string; duration: number; fullBody: boolean; fragment: string; tags: string; femaleTags: string }[]</returns>
    public static JsValue GetCatalog() => Sdk.Call<JsValue>("ui", "EmoteWheel", "getCatalog");
}
